class Pessoa {
  final int? id;
  final String nome;
  final int idade;
  const Pessoa({this.id, required this.nome,
    required this.idade});
  Pessoa copyWith({int? idade}) => Pessoa(
    id: id, nome: nome, idade: idade ?? this.idade);
}
void main() {
  final p = Pessoa(id: 7, nome: 'Lia', idade: 20);
  final nova = p.copyWith(idade: 21);
  print('${nova.id} | ${nova.nome} | ${nova.idade}');
}

class Pessoa {
  final String nome;
  const Pessoa(this.nome);
  Pessoa copyWith({String? nome}) =>
      Pessoa(nome ?? this.nome);
}
void main() {
  final p = Pessoa('Ana');
  print(p.copyWith(nome: null).nome);
}

class Pessoa {
  final int idade;
  Pessoa.fromMap(Map<String, dynamic> map)
      : idade = (map['idade'] as num).toInt();
}
void main() {
  final p = Pessoa.fromMap({'idade': 18.9});
  print(p.idade);
}

class Valores {
  final List<int> _itens = [];
  void add(int n) {
    if (!_itens.any((x) => x == n)) _itens.add(n);
  }
  int total() => _itens.fold(0, (s, x) => s + x);
}
void main() {
  final v = Valores();
  v.add(40); v.add(10); v.add(40);
  print(v.total());
}

class Valores {
  final List<int> _itens = [5, 9, 4];
  void removerIndice(int i) { _itens.removeAt(i); }
  int total() => _itens.fold(0, (s, x) => s + x);
}
void main() {
  final v = Valores();
  v.removerIndice(1);
  print(v.total());
}

class Servico {
  bool _concluido = false;
  final List<int> _itens = [];
  void adicionar(int valor) {
    if (_concluido) throw StateError('Concluído');
    _itens.add(valor);
  }
  void concluir() { _concluido = true; }
}
void main() {
  final s = Servico();
  s.adicionar(8);
  s.concluir();
  s.adicionar(3);
}

class Pessoa {
  final int? id;
  const Pessoa({this.id});
}
Future<int> update(Pessoa p) async {
  if (p.id == null) return 0;
  return 1;
}
void main() async {
  print(await update(const Pessoa()));
}

Future<List<int>> listar() async => [3, 5, 7];
void main() async {
  final itens = await listar();
  print(itens.length);
}

class Tarefa {
  final bool done;
  const Tarefa(this.done);
  Tarefa copyWith({bool? done}) =>
      Tarefa(done ?? this.done);
}
void main() {
  final a = Tarefa(false);
  final b = a.copyWith(done: true);
  print('${a.done} / ${b.done}');
}

class Tarefa {
  final String key;
  final bool done;
  Tarefa(this.key, this.done);
}
Map<String, Object> atualizacao(Tarefa t) =>
    {'done': !t.done};
void main() {
  final t = Tarefa('abc', true);
  print(atualizacao(t)['done']);
}
